functions.setThing:
{
   var _loc3_;
   if(target.type == "头盔" || target.type == "衣服" || target.type == "武器" || target.type == "鞋" || target.type == "幸运符" || target.type == "戒指" || target.type == "宝石")
   {
      _loc3_ = target.type != "宝石" ? "item" : "stone";
      if("空格" == this[_loc3_].type)
      {
         this[_loc3_].setThing(target);
      }
      else
      {
         this._parent.backPack.setThing(this[_loc3_]);
         this[_loc3_].setThing(target);
      }
      this.flashInfo();
      return true;
   }
   return false;
}

functions.flashInfo:
{
