functions.makeItem:
{
   if(this.item.type == "空格" || this.stone.type == "空格")
   {
      return false;
   }
   var _loc5_;
   var _loc0_;
   var _loc4_;
   if(this.item.type != "幸运符")
   {
      if(this.item.type == "戒指")
      {
         if(this.stone.type == "空格")
         {
            return false;
         }
         switch(this.stone.name)
         {
            case "灵魂晶石":
               if(this.item.grade < 4)
               {
                  if(this.useGem(this.gradeSuccess[this.item.grade]))
                  {
                     this.item.grade += 1;
                     return true;
                  }
               }
               return false;
            case "灵魂王":
               if(this.item.grade < 4)
               {
                  if(this.useGem())
                  {
                     this.item.grade += 1;
                     return true;
                  }
               }
               return false;
            case "高级攻击宝石":
               if(this.item.mhdj < 10)
               {
                  if(this.useGem())
                  {
                     this.item.mhdj++;
                     this.item.attack += 10;
                     return true;
                  }
               }
               return false;
            case "高级减伤害宝石":
               if(this.item.mhdj < 10)
               {
                  if(this.useGem())
                  {
                     this.item.mhdj++;
                     this.item.reduceDamage += 1;
                     return true;
                  }
               }
               return false;
            case "高级经验宝石":
               if(this.item.mhdj < 10)
               {
                  if(this.useGem())
                  {
                     this.item.mhdj++;
                     this.item.defense += 4;
                     return true;
                  }
               }
               return false;
            case "幻魔之心":
               if(this.item.mhdj < 10)
